import { parseInput, type ContextArgument, type DataLayer } from "@meshfw/runtime";
import type { User, ReadUserInput } from "./user.types";
import { readUserInput } from "./user.validators";
import { tables } from "../schema";

export function bindUser(layer: DataLayer) {
  return Object.freeze({
    async read(input: ReadUserInput, ...[_context]: ContextArgument): Promise<User[]> {
      await parseInput(readUserInput, input);
      return layer.transaction(async (tx) => {
        return (await tx.selectAll(tables.user)) as User[];
      });
    },
  });
}
